import { Component, inject, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FinancialService } from '../../core/services/financial.service';
import { FinancialTableComponent } from '../../shared/components/financial-table/financial-table.component';
import { KpiCardComponent } from '../../shared/components/kpi-card/kpi-card.component';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, FinancialTableComponent, KpiCardComponent],
  templateUrl: './dashboard.component.html'
})
export class DashboardComponent {
  financialService = inject(FinancialService);
  Object = Object;

  // ETAPA 6: Lógica para Pontos Positivos Dinâmicos [cite: 18]
  pontosPositivos = computed(() => {
    const data = this.financialService.dashboardData();
    if (!data) return [];
    
    const items: string[] = [];
    const ind = data.indices;

    if (ind['margem_liquida'] > 10) items.push('✅ Margem Líquida sólida acima de 10%, indicando alta eficiência operacional.'); 
    if (ind['roa'] > 15) items.push('✅ Excelente retorno sobre ativos (ROA), demonstrando uso eficiente da estrutura.'); 
    
    const lucroLiq = data.tabela_dre?.find(r => r.conta.toLowerCase().includes('lucro liq'));
    if (lucroLiq && lucroLiq.perc > 0) {
      items.push(`✅ Crescimento de ${lucroLiq.perc}% no Lucro Líquido comparado ao período anterior.`);
    }

    return items;
  });

  // ETAPA 6: Lógica para Pontos de Atenção Dinâmicos [cite: 19]
  pontosAtencao = computed(() => {
    const data = this.financialService.dashboardData();
    if (!data) return [];
    
    const items: string[] = [];
    const ind = data.indices;

    if (ind['liq_corrente'] < 1.0) items.push('⚠️ Liquidez corrente abaixo de 1.0 indica risco imediato de insolvência.'); 
    if (ind['endiv_geral'] > 70) items.push('⚠️ Endividamento Geral crítico acima de 70%, comprometendo a autonomia financeira.'); 

    return items;
  });

  // ETAPA 4: Cores dinâmicas para os cards baseadas em tabelas de referência 
  getIndicatorClass(key: string, value: number): string {
    const k = key.toLowerCase();
    if (k.includes('liq_corrente')) {
      if (value < 1.0) return 'text-rose-600 bg-rose-50 border-rose-100'; // Crítico [cite: 37]
      if (value <= 1.5) return 'text-amber-600 bg-amber-50 border-amber-100'; // Atenção [cite: 38]
      return 'text-emerald-600 bg-emerald-50 border-emerald-100'; // Bom/Excelente [cite: 39]
    }
    
    if (k.includes('endiv_geral')) {
      if (value > 70) return 'text-rose-600 bg-rose-50 border-rose-100'; // Crítico [cite: 41]
      if (value > 50) return 'text-amber-600 bg-amber-50 border-amber-100'; // Atenção [cite: 41]
      return 'text-emerald-600 bg-emerald-50 border-emerald-100'; // Saudável [cite: 40]
    }

    if (k.includes('margem_liquida')) {
      if (value < 0) return 'text-rose-600 bg-rose-50 border-rose-100'; // Crítico [cite: 42]
      if (value < 5) return 'text-amber-600 bg-amber-50 border-amber-100'; // Baixa [cite: 43]
      return 'text-emerald-600 bg-emerald-50 border-emerald-100'; // Adequada/Boa [cite: 44]
    }

    return 'text-slate-600 bg-slate-50 border-slate-100';
  }

  // ETAPA 4: Texto interpretativo dinâmico 
  getIndicatorNote(key: string, value: number): string {
    const k = key.toLowerCase();
    if (k.includes('liq_corrente')) {
      if (value < 1.0) return '🚨 CRÍTICO: Dificuldade de pagar dívidas';
      if (value <= 1.5) return '⚠️ ATENÇÃO: Capacidade justa';
      return '✅ BOM: Capacidade adequada';
    }
    
    if (k.includes('endiv_geral')) {
      if (value > 70) return '🚨 CRÍTICO: Alto endividamento';
      if (value > 50) return '⚠️ ATENÇÃO: Endividamento moderado';
      return '✅ EXCELENTE: Baixo endividamento';
    }

    if (k.includes('margem_liquida')) {
      if (value < 0) return '🚨 CRÍTICO: Operação em Prejuízo';
      if (value < 5) return '⚠️ BAIXA: Rentabilidade fraca';
      return '✅ BOA: Rentabilidade sólida';
    }

    return 'Indicador processado via Emerald AI';
  }

  getAnosProcessados(anosObj: any): string {
    if (!anosObj) return '...';
    return Object.keys(anosObj).sort().join(' VS ');
  }

  formatKey(key: string): string {
    return key.replace(/_/g, ' ').toUpperCase();
  }

  getFormatType(key: string): 'currency' | 'percent' | 'number' {
    const k = key.toLowerCase();
    if (k.includes('margem') || k.includes('roa') || k.includes('perc') || k.includes('endiv')) return 'percent';
    if (k.includes('ebitda')) return 'currency';
    return 'number';
  }

  onFileSelected(event: any) {
    const files = event.target.files;
    if (files.length) {
      this.financialService.uploadFiles(Array.from(files)).subscribe({
        error: (err: any) => alert('Erro na análise: ' + (err.error?.error || 'Falha no servidor'))
      });
    }
  }

  print() { window.print(); } 
}
